import{_ as s,a0 as d,w as r,s as l,I as n,x as e,a1 as o,A as p,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"新蠕蟲能感染 Linux 系統和嵌入式設備！ | LCTT x X-CMD","titleTemplate":false,"description":"新蠕蟲能感染 Linux 系統和嵌入式設備！ | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"新蠕蟲能感染 Linux 系統和嵌入式設備！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"新蠕蟲能感染 Linux 系統和嵌入式設備！ | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/This new worm targets Linux PCs and embedded devices","title":"新蠕蟲能感染 Linux 系統和嵌入式設備！","tag":"201312","desc":""},"relativePath":"201312/This new worm targets Linux PCs and embedded devices.md","filePath":"[post].md"}'),u={name:"201312/This new worm targets Linux PCs and embedded devices.md"};function m(x,t,P,T,C,L){const i=d("Link");return r(),l("div",null,[t[14]||(t[14]=n("h1",{id:"新蠕蟲能感染-linux-系統和嵌入式設備",tabindex:"-1"},[e("新蠕蟲能感染 Linux 系統和嵌入式設備！ "),n("a",{class:"header-anchor",href:"#新蠕蟲能感染-linux-系統和嵌入式設備","aria-label":"Permalink to “新蠕蟲能感染 Linux 系統和嵌入式設備！”"},"​")],-1)),t[15]||(t[15]=n("p",null,[n("strong",null,"來自賽門鐵克研究員的消息，這個病毒通過2012年出現的 PHP 漏洞傳播")],-1)),t[16]||(t[16]=n("p",null,"據美國國際數據集團（IDG）的新聞 —— 一個新的蠕蟲病毒將目標指向那些運行了 Linux 和 PHP 的 x86 架構計算機，其變種還會對運行在其他芯片架構上的設備（諸如家用路由器和機頂盒）造成威脅。",-1)),t[17]||(t[17]=n("p",null,"根據賽門鐵克研究員的介紹，這種病毒利用 php-cgi 上的一個漏洞進行傳播，這個 php-cgi 組件的功能是允許 PHP 代碼在通用網關接口（CGI）的配置環境下被執行。此漏洞的代號為 CVE-2012-1823（通過這個漏洞，攻擊者可以遠程執行任意代碼，所以這種漏洞又叫“遠程任意代碼執行漏洞” —— 譯者注）。2012年5月份，PHP 5.4.3 和 PHP 5.3.13 這兩個版本已經打上補丁修復了這個漏洞。",-1)),n("p",null,[t[1]||(t[1]=e("這個賽門鐵克的研究員在",-1)),o(i,{href:"http://www.symantec.com/connect/blogs/linux-worm-targeting-hidden-devices"},{default:p(()=>[...t[0]||(t[0]=[e("Blog",-1)])]),_:1}),t[2]||(t[2]=e("中寫道：這個名為“Linux.Darlloz”的新蠕蟲病毒基於去年10月份放出的 PoC 代碼（PoC：proof of concept，概念驗證。利用目標計算機的漏洞，為對其進行攻擊而設計的代碼稱為 exploit，而一個沒有充分利用漏洞的 exploit，就是 PoC —— 譯者注）。",-1))]),t[18]||(t[18]=a("<p>“在傳播過程中，這段蠕蟲代碼會隨機產生 IP 地址，通過特殊途徑，利用普通的用户名密碼發送 HTTP POST 請求，探測漏洞”，研究員解釋道：“如果一個目標沒有打上 CVE-2012-1823 的補丁，這台機器就會從病毒服務器下載蠕蟲病毒，之後尋找下一個目標。”</p><p>這個唯一的蠕蟲變種目前為止只感染了 x86 系統，這是因為這個病毒的二進制格式為 Intel 架構下的 ELF （Executable and Linkable Format）格式。</p><p>然而這個研究員警告説，黑客也為其他架構開發了病毒，包括 ARM，PPC，MIPS 和 MIPSEL。</p><p>這些計算機架構主要用於諸如家用路由器、網絡監視器、機頂盒以及其他嵌入式設備。</p><p>“攻擊者顯然試圖在最大範圍內感染運行 Linux 的設備”，研究員又説：“然而我們還沒有證實他們有沒有攻擊非 PC 設備。”</p><p>很多嵌入式設備的固件都使用 Linux 作為操作系統，並且使用 PHP 作為 Web 服務管理界面。這些設備比 PC 機 或服務器更容易被攻陷，因為它們不會經常更新軟件。</p><p>在嵌入式設備為一個漏洞打上補丁，從來都不是件容易的事。很多廠商都不會定期公佈更新信息，而當他們公佈時，用户也不會被告知説這些更新解決了哪些安全問題。</p><p>並且，在嵌入式設備上更新軟件比在計算機上需要更多的工作，以及更多的技術知識。用户需要知道哪些網站能提供這些更新，然後下載下來，通過 Web 界面更新到他們的設備中。</p><p>“很多用户也許壓根就不知道他們家裏或辦公室的設備存在漏洞，”囉嗦的研究員説：“我們面臨的另一個問題是，即使用户注意到他們用的是有漏洞的設備，這些設備的供應商卻沒有提供補丁，原因是技術落後，或者完全就是硬件的限制：內存不足，或 CPU 太慢，不足以支持這些軟件的新版本。”</p><p>“為了保護他們的設備免受蠕蟲感染，用户需要確認這些設備是否運行在最新的固件版本上，必要的話，升級固件，設置高強度的管理員密碼，在防火牆那兒，或任何獨立的設備那兒，屏蔽任何對 -/cgi-bin/php, -/cgi-bin/php5, -/cgi-bin/php-cgi, -/cgi-bin/php.cgi and -/cgi-bin/php4 的 HTTP POST 請求。”沒完沒了的賽門鐵克研究員説道。</p><hr>",11)),n("p",null,[t[4]||(t[4]=e("via: ",-1)),o(i,{href:"http://www.computerworld.com/s/article/9244409/This_new_worm_targets_Linux_PCs_and_embedded_devices?taxonomyId=122"},{default:p(()=>[...t[3]||(t[3]=[e("http://www.computerworld.com/s/article/9244409/This_new_worm_targets_Linux_PCs_and_embedded_devices?taxonomyId=122",-1)])]),_:1})]),n("p",null,[t[7]||(t[7]=e("譯者：",-1)),o(i,{href:"https://github.com/bazz2"},{default:p(()=>[...t[5]||(t[5]=[e("bazz2",-1)])]),_:1}),t[8]||(t[8]=e(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:p(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=e("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[9]||(t[9]=[e("LCTT",-1)])]),_:1}),t[12]||(t[12]=e(" 原創翻譯，",-1)),o(i,{href:"http://linux.cn/"},{default:p(()=>[...t[10]||(t[10]=[e("Linux中國",-1)])]),_:1}),t[13]||(t[13]=e(" 榮譽推出",-1))])])}const b=s(u,[["render",m]]);export{f as __pageData,b as default};
